// Pick which certifications are worth spending a search on, and build
// the query. Every call downstream costs money, so this node exists to
// not make most of them.

const certs = $('Get certifications').all().map((i) => i.json);
const existing = $('Get existing resources').all().map((i) => i.json);

const countByCert = new Map();
for (const r of existing) {
  countByCert.set(r.certification_id, (countByCert.get(r.certification_id) ?? 0) + 1);
}

// Known hosts, so an already-proposed or already-stored URL is never
// offered again. Compared on hostname+path, ignoring query strings and
// trailing slashes, because ?ranMID=42 does not make it a new course.
const normalise = (u) => {
  try {
    const { hostname, pathname } = new URL(u);
    return (hostname + pathname).replace(/\/$/, '').toLowerCase();
  } catch {
    return u;
  }
};
const known = new Set(existing.map((r) => normalise(r.url)));

const out = [];
for (const c of certs) {
  const have = countByCert.get(c.id) ?? 0;

  // Four is enough for a plan to draw on. Certifications already at four
  // are skipped entirely — this workflow exists to fill the 16 that have
  // nothing, not to pile a fifth Udemy course onto AWS SAA.
  if (have >= 4) continue;

  out.push({
    json: {
      certification_id: c.id,
      name: c.name,
      short_name: c.short_name,
      provider: c.provider,
      have,
      known: [...known],
      // Deliberately narrow. "AWS SAA" alone returns bootcamp spam; the
      // words below bias toward the kinds of page worth linking.
      query: `${c.name} (${c.short_name}) official study guide OR free course OR documentation OR practice exam`,
    },
  });
}

if (out.length === 0) {
  // Nothing to do is a normal outcome, not an error.
  return [];
}

return out;

// Turn search hits into candidates the model can judge, and throw away
// the ones no model should have to look at.

const src = $('Which certs need help?').item.json;

const normalise = (u) => {
  try {
    const { hostname, pathname } = new URL(u);
    return (hostname + pathname).replace(/\/$/, '').toLowerCase();
  } catch {
    return u;
  }
};
const known = new Set(src.known);

// Aggregators, content farms and link-bait. A resource nobody would sit
// down and work through is not a resource.
const BLOCK = [
  'pinterest.', 'quora.com', 'reddit.com/r/', 'facebook.com',
  'slideshare.net', 'scribd.com', 'coursehero.com', 'chegg.com',
  'examtopics.com', 'braindump', 'dumps',
];

const results = $json.results ?? [];
const candidates = results
  .filter((r) => r.url && !known.has(normalise(r.url)))
  .filter((r) => !BLOCK.some((b) => r.url.toLowerCase().includes(b)))
  .slice(0, 6)
  .map((r) => ({
    url: r.url,
    title: r.title,
    snippet: String(r.content ?? '').slice(0, 400),
  }));

if (candidates.length === 0) return [];

return [{ json: { ...src, candidates } }];

// Unpack the model's answer and refuse to trust it.
//
// Two things get checked here rather than at review time, because a human
// triaging fifty rows will not check them: the url must be one we actually
// offered (models paraphrase urls), and confidence must clear a bar worth
// a person's attention.

const src = $('Filter candidates').item.json;
const offered = new Map(src.candidates.map((c) => [c.url, c]));

// Which known platform a url is from, or null. Same map as the app's
// src/lib/resource-prefs.ts siteOf — match on host, never substring.
const siteOf = (url) => {
  let host;
  try { host = new URL(url).hostname.replace(/^www\./, '').toLowerCase(); } catch { return null; }
  const hosts = { 'youtube.com': 'YouTube', 'youtu.be': 'YouTube', 'udemy.com': 'Udemy', 'coursera.org': 'Coursera', 'freecodecamp.org': 'freeCodeCamp', 'pluralsight.com': 'Pluralsight', 'edx.org': 'edX', 'linkedin.com': 'LinkedIn Learning' };
  for (const d in hosts) { if (host === d || host.endsWith('.' + d)) return hosts[d]; }
  return null;
};

let picks = [];
try {
  // Gemini: responseMimeType application/json puts the JSON string in the
  // first candidate's first text part. It already matches {results: [...]}.
  const text = $json.candidates?.[0]?.content?.parts?.[0]?.text;
  picks = JSON.parse(text ?? '{"results":[]}').results ?? [];
} catch (e) {
  // A malformed answer is a dropped run, not a bad row in the database.
  return [];
}

const out = [];
for (const p of Array.isArray(picks) ? picks : []) {
  // The url must be one we handed it. This is the whole defence against a
  // confident, plausible, invented link — the same rule the advisor's
  // resourceIds follow, for the same reason.
  if (!offered.has(p.url)) continue;
  if (typeof p.confidence !== 'number' || p.confidence < 0.6) continue;

  out.push({
    json: {
      certification_id: src.certification_id,
      message:
        `Found a possible ${p.type} for ${src.name}: ${p.title} (${p.provider}). ` +
        `${p.free ? 'Appears free' : 'Appears paid'}. ${p.ai_reason} — ${p.url}`,
      confidence: Math.min(1, Math.max(0, p.confidence)),
      source_site: siteOf(p.url),
      // Exactly the shape of a certification_resources row, so accepting
      // this is a copy-paste rather than a retyping exercise.
      proposal: JSON.stringify({
        certification_id: src.certification_id,
        title: p.title,
        provider: p.provider,
        url: p.url,
        duration: p.duration,
        free: p.free,
        type: p.type,
        ai_reason: p.ai_reason,
        evidence: offered.get(p.url)?.snippet,
        found_at: new Date().toISOString(),
      }),
    },
  });
}

return out;
